estilos.css:
.profile-shell {
  width: 100%;
  display: grid;
  gap: 16px;
}

.profile-heading {
  display: grid;
  grid-template-columns: auto minmax(0,1fr);
  gap: 13px;
  align-items: center;
}

.profile-avatar {
  width: 58px;
  height: 58px;
  display: grid;
  place-items: center;
  border-radius: 18px;
  background: var(--primary);
  color: #fff;
  font-size: 17px;
  font-weight: 900;
  letter-spacing: .03em;
}

.profile-eyebrow {
  display: block;
  margin-bottom: 4px;
  color: var(--gold);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.profile-heading h1 {
  margin: 0;
  color: var(--primary);
  font-size: 23px;
  line-height: 1.1;
  letter-spacing: -.025em;
}

.profile-heading p {
  max-width: 620px;
  margin: 6px 0 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.5;
}

.profile-tabs {
  display: grid;
  grid-template-columns: repeat(3,minmax(0,1fr));
  gap: 6px;
  padding: 5px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: #f8fafc;
}

.profile-tabs button {
  min-height: 44px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: #667085;
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
}

.profile-tabs button.is-active {
  background: #fff;
  color: var(--primary);
  box-shadow: 0 1px 4px rgba(16,35,63,.10);
}

.profile-panels > section[hidden] {
  display: none !important;
}

.profile-form {
  display: grid;
  gap: 14px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 17px;
  background: #fff;
  box-shadow: 0 2px 8px rgba(16,35,63,.035);
}

.section-head h2,
.subsection-title h3 {
  margin: 0;
  color: var(--primary);
}

.section-head h2 { font-size: 18px; }
.subsection-title h3 { font-size: 15px; }

.section-head p,
.subsection-title p {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.5;
}

.field-grid {
  display: grid;
  gap: 12px;
}
.field-grid.two { grid-template-columns: repeat(2,minmax(0,1fr)); }
.field-grid.three { grid-template-columns: repeat(3,minmax(0,1fr)); }

.field {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.field span {
  color: #344054;
  font-size: 11px;
  font-weight: 800;
}

.field input,
.field select,
.field textarea {
  width: 100%;
  min-width: 0;
  min-height: 44px;
  padding: 10px 11px;
  border: 1px solid #d0d5dd;
  border-radius: 10px;
  background: #fff;
  color: var(--text);
  font: inherit;
  font-size: 13px;
  outline: none;
  box-sizing: border-box;
}

.field textarea {
  resize: vertical;
  line-height: 1.5;
}

.field input:focus,
.field select:focus,
.field textarea:focus {
  border-color: var(--primary-soft);
  box-shadow: 0 0 0 3px rgba(30,64,111,.08);
}

.section-divider {
  height: 1px;
  margin: 4px 0;
  background: var(--line);
}

.check-grid {
  display: grid;
  grid-template-columns: repeat(2,minmax(0,1fr));
  gap: 8px;
}

.check-option {
  min-height: 42px;
  display: flex;
  gap: 9px;
  align-items: center;
  padding: 9px 10px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: #fafbfc;
  color: #344054;
  font-size: 12px;
  cursor: pointer;
}

.check-option input {
  width: 17px;
  height: 17px;
  accent-color: var(--primary);
}

.profile-note {
  display: grid;
  gap: 4px;
  padding: 12px 13px;
  border: 1px solid #e6d7aa;
  border-radius: 12px;
  background: #fffaf0;
}

.profile-note strong {
  color: #76520d;
  font-size: 12px;
}

.profile-note span {
  color: #725c31;
  font-size: 11px;
  line-height: 1.45;
}

.form-actions {
  display: flex;
  justify-content: flex-end;
  padding-top: 2px;
}

.primary-button {
  min-height: 44px;
  padding: 0 18px;
  border: 0;
  border-radius: 11px;
  background: var(--primary);
  color: #fff;
  font-weight: 800;
  cursor: pointer;
}

.profile-toast {
  padding: 11px 13px;
  border-radius: 11px;
  background: #ecfdf3;
  color: #087443;
  font-size: 12px;
  font-weight: 800;
  text-align: center;
}

.profile-toast[hidden] {
  display: none !important;
}

@media (max-width: 620px) {
  .field-grid.two,
  .field-grid.three,
  .check-grid {
    grid-template-columns: 1fr;
  }

  .profile-tabs {
    grid-template-columns: 1fr;
  }

  .profile-heading {
    align-items: start;
  }
}
